def compute(vars):
    margin_2019 = vars["v1"]
    margin_2018 = vars["v2"]

    if margin_2019 > margin_2018:
        year = 2019
    elif margin_2018 > margin_2019:
        year = 2018
    else:
        year = None

    return {
        "value": year,
        "trace": {
            "gross_margin_2019": margin_2019,
            "gross_margin_2018": margin_2018,
            "output_meta": {"currency": None, "scale": None, "unit": "year"}
        }
    }
